const hours=Array.from({length:26},(_,i)=>i),selected=new Map();const bookingDates=[];const weekDays=['SUN','MON','TUE','WED','THU','FRI','SAT'],monthNames=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];let activeDate=0,dateWindowStart=0,visibleDateCount=4,activeBookingOwner='kitchen',announcementOwner='kitchen',activeCourtNumber=1,currentMatchVenue='kitchen';function makeVenueLogo(bg,fg,accent,text){const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><rect width="80" height="80" rx="20" fill="${bg}"/><circle cx="40" cy="40" r="34" fill="none" stroke="${accent}" stroke-width="2" stroke-dasharray="4 2" opacity="0.6"/><g transform="translate(40,32) scale(0.65)"><rect x="-14" y="-22" width="28" height="34" rx="9" fill="${fg}"/><rect x="-4" y="10" width="8" height="20" rx="3" fill="${fg}"/><circle cx="-5" cy="-10" r="2" fill="${bg}"/><circle cx="5" cy="-10" r="2" fill="${bg}"/><circle cx="0" cy="0" r="2" fill="${bg}"/><circle cx="16" cy="-16" r="8" fill="${accent}"/></g><text x="40" y="66" fill="#ffffff" font-family="Inter,system-ui,sans-serif" font-size="9" font-weight="900" text-anchor="middle" letter-spacing="1">${text}</text></svg>`;return 'data:image/svg+xml;utf8,'+encodeURIComponent(svg)}
